const data = $json;
const items = [];

function agregarDestino(canal, identificador, mensaje) {
  if (!identificador) return;
  items.push({ json: { canal, identificador, mensaje } });
}

for (const t of data.tecnicos) {
  const lineasTickets = t.ticketsHoy.length
    ? t.ticketsHoy.map((tk) => {
        const alerta = tk.estadoSla === 'vencido' ? ' ⚠️ SLA VENCIDO' : tk.estadoSla === 'en_riesgo' ? ' ⏰ SLA en riesgo' : '';
        return `- #${tk.numeroTicket} ${tk.titulo} (${tk.clienteNombre}, ${tk.prioridad})${alerta}`;
      }).join('\n')
    : 'Sin tickets activos asignados.';
  const lineasPreventivos = t.preventivosProximos.length
    ? t.preventivosProximos.map((p) => `- ${p.titulo} (${p.clienteNombre}) — ${p.proximaFecha}`).join('\n')
    : null;

  let mensaje = `☀️ Buenos días ${t.usuarioNombre.split(' ')[0]}, tus tickets activos:\n${lineasTickets}`;
  if (lineasPreventivos) mensaje += `\n\nPreventivos próximos (7 días):\n${lineasPreventivos}`;

  agregarDestino('TELEGRAM', t.telegramChatId, mensaje);
  agregarDestino('WHATSAPP', t.whatsappTelefono, mensaje);
}

for (const s of data.staff) {
  const r = s.resumen;
  const mensaje = `📊 Resumen diario NexIT\n\nTickets activos: ${r.ticketsActivos}\nCríticos/altos sin asignar: ${r.criticosSinAsignar.length}\nCumplimiento SLA: ${r.slaCumplimiento.pctCumplimiento ?? '—'}%\nPreventivos vencidos: ${r.preventivosPorVigencia.vencido}`;
  agregarDestino('TELEGRAM', s.telegramChatId, mensaje);
  agregarDestino('WHATSAPP', s.whatsappTelefono, mensaje);
}

return items;
